"""Base class and common contracts for memory benchmark baselines."""

import time
from abc import ABC, abstractmethod
from collections.abc import Callable
from typing import Any

import litellm
from pydantic import BaseModel, Field

from eval.cache import DiskCache
from eval.datasets.models import EvalQuestion


class BaselineOutput(BaseModel):
    """Output generated by a benchmark baseline for a question."""

    prediction: str
    prompt_tokens: int = 0
    completion_tokens: int = 0
    total_tokens: int = 0
    latency_ms: float = 0.0
    context_used: str = ""
    metadata: dict[str, Any] = Field(default_factory=dict)


class BaseBaseline(ABC):
    """Abstract baseline agent representing a conversational memory architecture."""

    def __init__(
        self,
        name: str,
        model: str = "gemini/gemini-1.5-flash",
        cache: DiskCache | None = None,
        llm_client: Callable[..., Any] | None = None,
        **kwargs: Any,
    ) -> None:
        self.name = name
        self.model = model
        self.cache = cache
        self.llm_client = llm_client
        self.kwargs = kwargs

    @abstractmethod
    async def setup(self, item: EvalQuestion) -> None:
        """Ingests background conversation / history prior to answering."""
        pass

    @abstractmethod
    async def answer(self, item: EvalQuestion) -> BaselineOutput:
        """Generates answer to question and tracks token usage and latency."""
        pass

    async def teardown(self) -> None:
        """Cleans up internal resources, stores, or connections."""
        return None

    async def _generate_llm_response(
        self, prompt: str, system_prompt: str | None = None, **kwargs: Any
    ) -> tuple[str, int, int, float]:
        """Generate an LLM response with caching, token estimation, and latency tracking.

        Returns:
            Tuple of (response_text, prompt_tokens, completion_tokens, latency_ms).
        """
        combined_prompt = f"{system_prompt or ''}\n\n{prompt}".strip()
        start_time = time.perf_counter()

        # Check disk cache first
        if self.cache:
            cached = self.cache.get(self.model, combined_prompt, **kwargs)
            if cached is not None:
                elapsed_ms = (time.perf_counter() - start_time) * 1000.0
                prompt_tokens = len(combined_prompt.split())
                completion_tokens = len(cached.split())
                return cached, prompt_tokens, completion_tokens, elapsed_ms

        # If custom llm_client is provided (e.g. for testing / mocking)
        if self.llm_client is not None:
            res = self.llm_client(prompt=combined_prompt, model=self.model, **kwargs)
            if hasattr(res, "__await__"):
                res = await res
            if isinstance(res, tuple):
                text = str(res[0])
                prompt_tokens = int(res[1]) if len(res) > 1 else len(combined_prompt.split())
                completion_tokens = int(res[2]) if len(res) > 2 else len(text.split())
            else:
                text = str(res)
                prompt_tokens = len(combined_prompt.split())
                completion_tokens = len(text.split())

            elapsed_ms = (time.perf_counter() - start_time) * 1000.0
            if self.cache:
                self.cache.set(self.model, combined_prompt, text, **kwargs)
            return text, prompt_tokens, completion_tokens, elapsed_ms

        # Live call via LiteLLM
        messages = []
        if system_prompt:
            messages.append({"role": "system", "content": system_prompt})
        messages.append({"role": "user", "content": prompt})

        response = await litellm.acompletion(
            model=self.model,
            messages=messages,
            temperature=kwargs.get("temperature", 0.0),
            max_tokens=kwargs.get("max_tokens", 512),
        )

        text = response.choices[0].message.content or ""
        usage = getattr(response, "usage", None)
        prompt_tokens = getattr(usage, "prompt_tokens", len(combined_prompt.split()))
        completion_tokens = getattr(usage, "completion_tokens", len(text.split()))

        elapsed_ms = (time.perf_counter() - start_time) * 1000.0

        if self.cache:
            self.cache.set(self.model, combined_prompt, text, **kwargs)

        return text, prompt_tokens, completion_tokens, elapsed_ms
